mapper.select:
SELECT f.*,u.USER_NAME AS CREATOR_NAME
  FROM CONTENT_FILES f LEFT JOIN USERS u ON u.USER_ID=f.CREATED_BY
 WHERE f.SCOPE_TYPE=#{scopeType} AND f.DELETED_YN='N'

     AND f.OWNER_USER_ID=#{ownerUserId}
     AND f.WS_ID=#{wsId}
     AND f.PROJ_ID=#{projId}


 ORDER BY f.CREATED_AT DESC,f.CONTENT_FILE_ID DESC

SELECT *
  FROM (
    SELECT f.*, u.USER_NAME AS CREATOR_NAME
      FROM CONTENT_FILES f
      LEFT JOIN USERS u ON u.USER_ID = f.CREATED_BY
     WHERE f.SCOPE_TYPE = #{scopeType}
       AND f.DELETED_YN = 'N'

         AND f.OWNER_USER_ID = #{ownerUserId}
         AND f.WS_ID = #{wsId}
         AND f.PROJ_ID = #{projId}


     ORDER BY f.CREATED_AT DESC, f.CONTENT_FILE_ID DESC
  )
 WHERE ROWNUM <= #{limit}

SELECT * FROM (
  SELECT q.*, ROWNUM rn FROM (
    SELECT f.*,u.USER_NAME AS CREATOR_NAME
      FROM CONTENT_FILES f LEFT JOIN USERS u ON u.USER_ID=f.CREATED_BY
     WHERE 
     ORDER BY

        LOWER(f.ORIGINAL_NAME) ASC, f.CONTENT_FILE_ID DESC
        f.FILE_SIZE DESC, f.CONTENT_FILE_ID DESC
        f.FILE_SIZE ASC, f.CONTENT_FILE_ID DESC
        f.CREATED_AT ASC, f.CONTENT_FILE_ID ASC
        f.CREATED_AT DESC, f.CONTENT_FILE_ID DESC

  ) q WHERE ROWNUM <= #{offset}+#{size}
) WHERE rn > #{offset}

SELECT CASE
  WHEN #{scopeType,jdbcType=VARCHAR}='GROUP' AND EXISTS (
    SELECT 1
      FROM WORKSPACES w
      LEFT JOIN WS_MEMBERS wm
        ON wm.WS_ID = w.WS_ID
       AND wm.USER_ID = #{userId,jdbcType=NUMERIC}
     WHERE w.WS_ID = #{wsId,jdbcType=NUMERIC}
       AND (
            w.OWNER_ID = #{userId,jdbcType=NUMERIC}
            OR UPPER(NVL(wm.WS_ROLE, 'MEMBER')) = 'ADMIN'
       )
  ) THEN 1
  WHEN #{scopeType,jdbcType=VARCHAR}='PROJECT' AND EXISTS (
    SELECT 1
      FROM PROJECTS p
      LEFT JOIN PROJ_MEMBERS pm
        ON pm.PROJ_ID = p.PROJ_ID
       AND pm.USER_ID = #{userId,jdbcType=NUMERIC}
     WHERE p.PROJ_ID = #{projId,jdbcType=NUMERIC}
       AND (
            p.LEADER_ID = #{userId,jdbcType=NUMERIC}
            OR UPPER(NVL(pm.PROJ_ROLE, 'MEMBER')) IN ('ADMIN', 'LEADER', 'OWNER', 'PM')
       )
  ) THEN 1
  ELSE 0
END
FROM DUAL
